@triton.jit
def _gram_matrix_kernel(
    A_ptr,
    G_ptr,
    M,
    N,
    stride_ab,
    stride_am,
    stride_an,
    stride_gb,
    stride_gn1,
    stride_gn2,
    BLOCK_N: tl.constexpr,
):
    """Compute one BLOCK_N x BLOCK_N tile of G = X^T X for a batch element.

    The contraction runs over M rows of X (X is either A or A^T, selected by
    the host through the stride arguments). Each program accumulates its tile
    with rank-1 outer products, so G is produced with a tiled grid instead
    of one serial program per matrix.

    G is padded to BLOCK_N x BLOCK_N (power of two) and stored column-major
    (the layout expected by the Jacobi kernel: logical G[i, j] lives at
    i * stride_gn1 + j * stride_gn2 with stride_gn1 == 1). Masked memory ops
    are avoided entirely on this backend (they miscompile / can leak OOB
    stores): out-of-range indices are clamped so every load stays in bounds,
    and the padding lanes are zeroed with a register-level where afterwards,
    which keeps the padded rows/columns of G exactly zero.
    """
    batch_id = tl.program_id(0)
    pid_i = tl.program_id(1)
    pid_j = tl.program_id(2)
    A_batch = A_ptr + batch_id * stride_ab
    G_batch = G_ptr + batch_id * stride_gb

    i_idx = pid_i * BLOCK_N + tl.arange(0, BLOCK_N)
    j_idx = pid_j * BLOCK_N + tl.arange(0, BLOCK_N)
    # Clamp to keep every load in bounds, then zero the padding lanes in
    # registers (the padded gram columns are exactly zero by construction).
    i_load = tl.minimum(i_idx, N - 1)
    j_load = tl.minimum(j_idx, N - 1)

    acc = tl.zeros((BLOCK_N, BLOCK_N), dtype=tl.float32)
    for k in range(M):
        a_i = tl.load(A_batch + k * stride_am + i_load * stride_an)
        a_j = tl.load(A_batch + k * stride_am + j_load * stride_an)
        a_i = tl.where(i_idx < N, a_i, 0.0)
        a_j = tl.where(j_idx < N, a_j, 0.0)
        acc += a_i[:, None] * a_j[None, :]

    offs = i_idx[:, None] * stride_gn1 + j_idx[None, :] * stride_gn2
    tl.store(G_batch + offs, acc)


@triton.jit
def _cond_fused_kernel(
    A_ptr,
    G_ptr,
    out_ptr,
    M,
    stride_ab,
    stride_am,
    stride_an,
    stride_gb,
    stride_gn1,
    stride_gn2,
    stride_ob,
    GN: tl.constexpr,
    BLOCK_N: tl.constexpr,
    MAX_ITER: tl.constexpr,
    p_mode: tl.constexpr,
):
    """Fused gram + Jacobi + cond for small matrices (GN <= 32).

    Single kernel launch for the whole p in (None, 2, -2) path: builds the
    gram tile in registers with outer products, runs the early-exit Jacobi on
    the column-major G buffer, then reduces the diagonal to the condition
    number. The Jacobi phase is identical to _jacobi_eigenvalues_kernel.

    G is padded to BLOCK_N x BLOCK_N (power of two). No masked memory ops:
    loads use clamped indices and the padding lanes are zeroed with
    register-level where, so the padded rows/columns stay exactly zero and
    every rotation only touches valid indices (p, q < GN).
    """
    batch_id = tl.program_id(0)
    A_batch = A_ptr + batch_id * stride_ab
    G_batch = G_ptr + batch_id * stride_gb

    r_idx = tl.arange(0, BLOCK_N)
    r_load = tl.minimum(r_idx, GN - 1)

    # ---- gram phase: G = X^T X, one [BLOCK_N, BLOCK_N] register tile
    acc = tl.zeros((BLOCK_N, BLOCK_N), dtype=tl.float32)
    for k in range(M):
        a_i = tl.load(A_batch + k * stride_am + r_load * stride_an)
        a_i = tl.where(r_idx < GN, a_i, 0.0)
        acc += a_i[:, None] * a_i[None, :]
    offs = r_idx[:, None] * stride_gn1 + r_idx[None, :] * stride_gn2
    tl.store(G_batch + offs, acc)

    # ---- Jacobi phase (identical to _jacobi_eigenvalues_kernel)
    finished = 0
    for sweep in range(MAX_ITER):
        if finished == 0:
            rotated = 0
            for p in range(GN):
                for q in range(p + 1, GN):
                    app = tl.load(G_batch + p * stride_gn2 + p * stride_gn1)
                    aqq = tl.load(G_batch + q * stride_gn2 + q * stride_gn1)
                    apq = tl.load(G_batch + p * stride_gn2 + q * stride_gn1)

                    abs_apq = tl.abs(apq)
                    do_rot = abs_apq > 1e-15
                    col_p = tl.load(G_batch + p * stride_gn2 + r_idx * stride_gn1)
                    col_q = tl.load(G_batch + q * stride_gn2 + r_idx * stride_gn1)
                    if do_rot:
                        tau = (aqq - app) / (2.0 * apq)
                        t = tl.where(
                            tau >= 0.0,
                            1.0 / (tau + tl.sqrt(1.0 + tau * tau)),
                            -1.0 / (-tau + tl.sqrt(1.0 + tau * tau)),
                        )
                        c = 1.0 / tl.sqrt(1.0 + t * t)
                        s = t * c

                        new_app = c * c * app - 2.0 * s * c * apq + s * s * aqq
                        new_aqq = s * s * app + 2.0 * s * c * apq + c * c * aqq

                        new_p = c * col_p - s * col_q
                        new_q = s * col_p + c * col_q
                        new_p = tl.where(
                            r_idx == p, new_app, tl.where(r_idx == q, 0.0, new_p)
                        )
                        new_q = tl.where(
                            r_idx == q, new_aqq, tl.where(r_idx == p, 0.0, new_q)
                        )
                        tl.store(
                            G_batch + p * stride_gn2 + r_idx * stride_gn1,
                            new_p,
                        )
                        tl.store(
                            G_batch + q * stride_gn2 + r_idx * stride_gn1,
                            new_q,
                        )
                        tl.store(
                            G_batch + r_idx * stride_gn2 + p * stride_gn1,
                            new_p,
                        )
                        tl.store(
                            G_batch + r_idx * stride_gn2 + q * stride_gn1,
                            new_q,
                        )
                    rotated += do_rot.to(tl.int32)
            if rotated == 0:
                finished = 1

    # ---- cond phase from the diagonal of the padded column-major G buffer
    diag = tl.load(G_batch + r_idx * stride_gn2 + r_idx * stride_gn1)
    eig = tl.maximum(diag, 0.0)
    sigma = tl.sqrt(eig)
    sigma_max = tl.max(sigma, axis=0)
    sigma_masked = tl.where(r_idx < GN, sigma, 1e30)
    sigma_min = tl.min(sigma_masked, axis=0)
    if p_mode == 0:
        cond = tl.where(sigma_min > 1e-30, sigma_max / sigma_min, 1e30)
    else:
        cond = tl.where(sigma_max > 1e-30, sigma_min / sigma_max, 0.0)
    tl.store(out_ptr + batch_id * stride_ob, cond)


@triton.jit
def _jacobi_eigenvalues_kernel(
    G_ptr,
    eigvals_ptr,
    stride_gb,
    stride_gn1,
    stride_gn2,
    stride_eb,
    stride_en,
    N: tl.constexpr,
    BLOCK_N: tl.constexpr,
    MAX_ITER: tl.constexpr,
):
    """Jacobi eigenvalue algorithm for symmetric matrix.
    Computes eigenvalues of a symmetric NxN matrix in-place.

    G is stored column-major (H = G^T row-major): the p-th *column* of the
    logical matrix lives at ``G_ptr + p * stride_gn2 + r * stride_gn1``, i.e.
    a contiguous row of H. Every rotation only reads and rewrites whole
    columns p and q, so all vector accesses are contiguous, and symmetry is
    preserved by the strided mirror writes (the scalar version wrote both
    G[r, p] and G[p, r]).

    G is padded to BLOCK_N x BLOCK_N (power of two): the vector ops span the
    full padded width without masks (masked memory ops miscompile on this
    backend), and the padded rows/columns hold exact zeros that stay zero
    under every rotation.

    Early exit: once a full sweep applies no rotation, the matrix is diagonal
    (within the 1e-15 threshold) and the remaining sweeps would be bit-exact
    no-ops, so we stop instead of spinning through MAX_ITER sweeps.
    """
    batch_id = tl.program_id(0)
    G_batch = G_ptr + batch_id * stride_gb
    E_batch = eigvals_ptr + batch_id * stride_eb

    r_idx = tl.arange(0, BLOCK_N)

    finished = 0
    for sweep in range(MAX_ITER):
        if finished == 0:
            rotated = 0
            for p in range(N):
                for q in range(p + 1, N):
                    # Diagonal and off-diagonal pivots, read from the two
                    # column-rows that this rotation is about to rewrite.
                    app = tl.load(G_batch + p * stride_gn2 + p * stride_gn1)
                    aqq = tl.load(G_batch + q * stride_gn2 + q * stride_gn1)
                    apq = tl.load(G_batch + p * stride_gn2 + q * stride_gn1)

                    # Skip if already zero (use tighter threshold for better convergence)
                    abs_apq = tl.abs(apq)
                    do_rot = abs_apq > 1e-15
                    # Column loads are unconditional and in-bounds (padded
                    # buffer): issuing them before the branch lets their
                    # latency overlap with the scalar rotation math.
                    col_p = tl.load(G_batch + p * stride_gn2 + r_idx * stride_gn1)
                    col_q = tl.load(G_batch + q * stride_gn2 + r_idx * stride_gn1)
                    if do_rot:
                        # Compute rotation angle
                        tau = (aqq - app) / (2.0 * apq)
                        # t = sign(tau) / (|tau| + sqrt(1 + tau^2))
                        t = tl.where(
                            tau >= 0.0,
                            1.0 / (tau + tl.sqrt(1.0 + tau * tau)),
                            -1.0 / (-tau + tl.sqrt(1.0 + tau * tau)),
                        )
                        c = 1.0 / tl.sqrt(1.0 + t * t)
                        s = t * c

                        new_app = c * c * app - 2.0 * s * c * apq + s * s * aqq
                        new_aqq = s * s * app + 2.0 * s * c * apq + c * c * aqq

                        # Vectorized rotation of columns p and q: one vector
                        # load / store per column instead of N scalar pairs.
                        new_p = c * col_p - s * col_q
                        new_q = s * col_p + c * col_q
                        # Fix the 2x2 pivot block: G[p,p], G[q,q] get the
                        # rotated diagonal, G[p,q] = G[q,p] = 0.
                        new_p = tl.where(
                            r_idx == p, new_app, tl.where(r_idx == q, 0.0, new_p)
                        )
                        new_q = tl.where(
                            r_idx == q, new_aqq, tl.where(r_idx == p, 0.0, new_q)
                        )
                        tl.store(
                            G_batch + p * stride_gn2 + r_idx * stride_gn1,
                            new_p,
                        )
                        tl.store(
                            G_batch + q * stride_gn2 + r_idx * stride_gn1,
                            new_q,
                        )
                        # Mirror writes (logical rows p/q = strided columns of
                        # the column-major layout): keeps the symmetric twin
                        # cells fresh, exactly like the scalar version wrote
                        # both G[r, p] and G[p, r].
                        tl.store(
                            G_batch + r_idx * stride_gn2 + p * stride_gn1,
                            new_p,
                        )
                        tl.store(
                            G_batch + r_idx * stride_gn2 + q * stride_gn1,
                            new_q,
                        )
                    rotated += do_rot.to(tl.int32)
            if rotated == 0:
                finished = 1

    # Store diagonal as eigenvalues
    for i in range(N):
        val = tl.load(G_batch + i * stride_gn2 + i * stride_gn1)
        tl.store(E_batch + i * stride_en, val)


@triton.jit
def _cond_from_eigvals_kernel(
    eigvals_ptr,
    out_ptr,
    stride_eb,
    stride_en,
    stride_ob,
    N: tl.constexpr,
    BLOCK_N: tl.constexpr,
    p_mode: tl.constexpr,
):
    """Compute condition number from eigenvalues of A^T A.
    p_mode: 0 = p=None/2 (max/min), 1 = p=-2 (min/max), 2 = p='nuc'
    """
    batch_id = tl.program_id(0)
    E_batch = eigvals_ptr + batch_id * stride_eb

    r_idx = tl.arange(0, BLOCK_N)
    # Clamped unmasked load + register-level where (masked memory ops
    # miscompile on this backend).
    r_load = tl.minimum(r_idx, N - 1)
    eig = tl.load(E_batch + r_load * stride_en)
    eig = tl.where(r_idx < N, eig, 0.0)
    # eigenvalues of A^T A should be non-negative
    eig = tl.maximum(eig, 0.0)
    sigma = tl.sqrt(eig)
    sigma_max = tl.max(sigma, axis=0)
    sigma_masked = tl.where(r_idx < N, sigma, 1e30)
    sigma_min = tl.min(sigma_masked, axis=0)
    sigma_sum = tl.sum(tl.where(r_idx < N, sigma, 0.0), axis=0)

    if p_mode == 0:
        # p=None or p=2: max(sigma) / min(sigma)
        cond = tl.where(sigma_min > 1e-30, sigma_max / sigma_min, 1e30)
    elif p_mode == 1:
        # p=-2: min(sigma) / max(sigma)
        cond = tl.where(sigma_max > 1e-30, sigma_min / sigma_max, 0.0)
    else:
        # p='nuc': needs inv singular values too, handled differently
        cond = sigma_sum

    tl.store(out_ptr + batch_id * stride_ob, cond)


@triton.jit
def _matrix_norm_kernel(
    A_ptr,
    out_ptr,
    stride_ab,
    stride_an1,
    stride_an2,
    stride_ob,
    N: tl.constexpr,
    norm_mode: tl.constexpr,
):
    """Compute matrix norms.
    norm_mode:
        0 = frobenius norm
        1 = max col abs sum (1-norm)
        2 = min col abs sum (-1 norm)
        3 = max row abs sum (inf-norm)
        4 = min row abs sum (-inf norm)
    """
    batch_id = tl.program_id(0)
    A_batch = A_ptr + batch_id * stride_ab

    if norm_mode == 0:
        # Frobenius norm
        acc = 0.0
        for i in range(N):
            for j in range(N):
                val = tl.load(A_batch + i * stride_an1 + j * stride_an2)
                acc += val * val
        result = tl.sqrt(acc)
    elif norm_mode == 1:
        # Max column absolute sum (1-norm)
        result = 0.0
        for j in range(N):
            col_sum = 0.0
            for i in range(N):
                val = tl.load(A_batch + i * stride_an1 + j * stride_an2)
                col_sum += tl.abs(val)
            result = tl.maximum(result, col_sum)
    elif norm_mode == 2:
        # Min column absolute sum (-1 norm)
        result = 1e30
        for j in range(N):
            col_sum = 0.0
            for i in range(N):
                val = tl.load(A_batch + i * stride_an1 + j * stride_an2)
                col_sum += tl.abs(val)
            result = tl.minimum(result, col_sum)
    elif norm_mode == 3:
        # Max row absolute sum (inf-norm)
        result = 0.0
        for i in range(N):
            row_sum = 0.0
            for j in range(N):
                val = tl.load(A_batch + i * stride_an1 + j * stride_an2)
                row_sum += tl.abs(val)
            result = tl.maximum(result, row_sum)
    else:
        # Min row absolute sum (-inf norm)
        result = 1e30
        for i in range(N):
            row_sum = 0.0
            for j in range(N):
                val = tl.load(A_batch + i * stride_an1 + j * stride_an2)
                row_sum += tl.abs(val)
            result = tl.minimum(result, row_sum)

    tl.store(out_ptr + batch_id * stride_ob, result)


@triton.jit
def _cond_norm_kernel(
    norm_a_ptr,
    norm_inv_ptr,
    out_ptr,
    stride_b,
):
    """Compute cond = norm(A) * norm(inv(A))."""
    batch_id = tl.program_id(0)
    na = tl.load(norm_a_ptr + batch_id * stride_b)
    ni = tl.load(norm_inv_ptr + batch_id * stride_b)
    tl.store(out_ptr + batch_id * stride_b, na * ni)


@triton.jit
def _nuc_cond_kernel(
    eigvals_a_ptr,
    eigvals_inv_ptr,
    out_ptr,
    stride_eb,
    stride_en,
    stride_ob,
    N: tl.constexpr,
):
    """Compute nuclear norm condition number from eigenvalues.
    nuc_cond = sum(svdvals(A)) * sum(svdvals(inv(A)))
    svdvals(A) = sqrt(eigvals(A^T A))
    svdvals(inv(A)) = sqrt(eigvals(inv(A)^T inv(A)))
    """
    batch_id = tl.program_id(0)
    Ea_batch = eigvals_a_ptr + batch_id * stride_eb
    Ei_batch = eigvals_inv_ptr + batch_id * stride_eb

    sum_a = 0.0
    sum_inv = 0.0
    for i in range(N):
        eig_a = tl.load(Ea_batch + i * stride_en)
        eig_a = tl.maximum(eig_a, 0.0)
        sum_a += tl.sqrt(eig_a)

        eig_inv = tl.load(Ei_batch + i * stride_en)
        eig_inv = tl.maximum(eig_inv, 0.0)
        sum_inv += tl.sqrt(eig_inv)

    tl.store(out_ptr + batch_id * stride_ob, sum_a * sum_inv)


def _compute_svd_cond(A, batch_size, m, n, p_mode):
    """Compute condition number via SVD (Jacobi eigenvalue decomposition).
    p_mode: 0=p2, 1=p-2, 2=nuc
    """
    device = A.device

    # A is contiguous on entry (see linalg_cond); the reshape below is a view.
    A_flat = A.reshape(batch_size, m, n)

    # Compute Gram matrix G = A^T A (shape: batch x n x n)
    # or if m < n, use A A^T (shape: batch x m x m).
    # G is stored column-major (Gt row-major with G = Gt^T): the Jacobi
    # kernel reads/writes whole columns of G, which become contiguous rows
    # of Gt. The gram kernels only need swapped strides, no data movement.
    if m >= n:
        gram_n = n
        # G = A^T A: contraction over the m rows of A.
        ctr = m
        stride_ctr = A_flat.stride(1)
        stride_idx = A_flat.stride(2)
    else:
        gram_n = m
        # G = A A^T: gram of A^T — swap the stride roles so the kernel loads
        # X[k, i] = A[i, k]; no host-side transposed copy is needed.
        ctr = n
        stride_ctr = A_flat.stride(2)
        stride_idx = A_flat.stride(1)
    stride_ab = A_flat.stride(0)

    BLOCK_N_J = max(2, triton.next_power_of_2(gram_n))
    max_iter = max(100, gram_n * 15)

    if gram_n <= 32:
        # Small matrices: one fused kernel for the whole pipeline
        # (gram + Jacobi + cond), a single launch. G is padded to
        # BLOCK_N_J x BLOCK_N_J (see kernel docstring).
        Gt = torch.empty(
            batch_size, BLOCK_N_J, BLOCK_N_J, dtype=torch.float32, device=device
        )
        G = Gt.transpose(1, 2)
        out = torch.empty(batch_size, dtype=torch.float32, device=device)
        _cond_fused_kernel[(batch_size,)](
            A_flat,
            G,
            out,
            ctr,
            stride_ab,
            stride_ctr,
            stride_idx,
            G.stride(0),
            G.stride(1),
            G.stride(2),
            out.stride(0),
            GN=gram_n,
            BLOCK_N=BLOCK_N_J,
            MAX_ITER=max_iter,
            p_mode=p_mode,
        )
        return out

    Gt = torch.empty(
        batch_size, BLOCK_N_J, BLOCK_N_J, dtype=torch.float32, device=device
    )
    G = Gt.transpose(1, 2)
    BLOCK_N_G = min(64, BLOCK_N_J)
    grid = (
        batch_size,
        triton.cdiv(BLOCK_N_J, BLOCK_N_G),
        triton.cdiv(BLOCK_N_J, BLOCK_N_G),
    )
    _gram_matrix_kernel[grid](
        A_flat,
        G,
        ctr,
        gram_n,
        stride_ab,
        stride_ctr,
        stride_idx,
        G.stride(0),
        G.stride(1),
        G.stride(2),
        BLOCK_N=BLOCK_N_G,
    )

    # Jacobi eigenvalue decomposition
    # More iterations needed for convergence on larger/ill-conditioned matrices
    eigvals = torch.empty(batch_size, gram_n, dtype=torch.float32, device=device)
    # GCU backend miscompiles this kernel for BLOCK_N >= 64 with num_warps > 1
    # (silently wrong eigenvalues, see compiler problem record); num_warps=1 is
    # correct at every width, so gate it by vector width.
    jacobi_kwargs = {"num_warps": 1} if BLOCK_N_J >= 64 else {}
    _jacobi_eigenvalues_kernel[(batch_size,)](
        G,
        eigvals,
        G.stride(0),
        G.stride(1),
        G.stride(2),
        eigvals.stride(0),
        eigvals.stride(1),
        N=gram_n,
        BLOCK_N=BLOCK_N_J,
        MAX_ITER=max_iter,
        **jacobi_kwargs,
    )

    # Compute condition number from eigenvalues
    out = torch.empty(batch_size, dtype=torch.float32, device=device)
    _cond_from_eigvals_kernel[(batch_size,)](
        eigvals,
        out,
        eigvals.stride(0),
        eigvals.stride(1),
        out.stride(0),
        N=gram_n,
        BLOCK_N=BLOCK_N_J,
        p_mode=p_mode,
    )
    return out


def _compute_norm_cond(A, batch_size, n, norm_mode):
    """Compute condition number via norm(A) * norm(inv(A)).

    Uses torch.linalg.inv for the inverse (numerically stable via LU),
    and Triton kernels for the norm computations.
    """
    device = A.device
    A_flat = A.reshape(batch_size, n, n).contiguous()

    # Compute norm of A
    norm_a = torch.zeros(batch_size, dtype=torch.float32, device=device)
    _matrix_norm_kernel[(batch_size,)](
        A_flat,
        norm_a,
        A_flat.stride(0),
        A_flat.stride(1),
        A_flat.stride(2),
        norm_a.stride(0),
        N=n,
        norm_mode=norm_mode,
    )

    # Compute inverse of A on CPU to avoid FlagGems Triton LU kernel dispatch
    # which may have reduced accuracy for small matrices. The inverse is then
    # moved back to the original device for the Triton norm kernel.
    Inv_A = torch.linalg.inv(A_flat.cpu()).to(device=device)

    # Compute norm of inv(A)
    norm_inv = torch.zeros(batch_size, dtype=torch.float32, device=device)
    _matrix_norm_kernel[(batch_size,)](
        Inv_A,
        norm_inv,
        Inv_A.stride(0),
        Inv_A.stride(1),
        Inv_A.stride(2),
        norm_inv.stride(0),
        N=n,
        norm_mode=norm_mode,
    )

    # cond = norm(A) * norm(inv(A))
    out = torch.zeros(batch_size, dtype=torch.float32, device=device)
    _cond_norm_kernel[(batch_size,)](
        norm_a,
        norm_inv,
        out,
        1,
    )
    return out


def _compute_nuc_cond(A, batch_size, n):
    """Compute nuclear norm condition number.
    nuc_cond = sum(svdvals(A)) * sum(svdvals(inv(A)))

    Uses torch.linalg.inv for stability, Triton for eigenvalue decomposition.
    """
    device = A.device
    A_flat = A.reshape(batch_size, n, n).contiguous()

    # Compute Gram matrix of A: G_A = A^T A (stored column-major and padded
    # to BLOCK_N_A x BLOCK_N_A, see _compute_svd_cond)
    BLOCK_N_A = max(2, triton.next_power_of_2(n))
    Gt_A = torch.empty(
        batch_size, BLOCK_N_A, BLOCK_N_A, dtype=torch.float32, device=device
    )
    G_A = Gt_A.transpose(1, 2)
    BLOCK_N_G = min(64, BLOCK_N_A)
    gram_grid = (
        batch_size,
        triton.cdiv(BLOCK_N_A, BLOCK_N_G),
        triton.cdiv(BLOCK_N_A, BLOCK_N_G),
    )
    _gram_matrix_kernel[gram_grid](
        A_flat,
        G_A,
        n,
        n,
        A_flat.stride(0),
        A_flat.stride(1),
        A_flat.stride(2),
        G_A.stride(0),
        G_A.stride(1),
        G_A.stride(2),
        BLOCK_N=BLOCK_N_G,
    )

    # Eigenvalues of G_A
    eigvals_a = torch.empty(batch_size, n, dtype=torch.float32, device=device)
    max_iter = max(30, n * 3)
    _jacobi_eigenvalues_kernel[(batch_size,)](
        G_A,
        eigvals_a,
        G_A.stride(0),
        G_A.stride(1),
        G_A.stride(2),
        eigvals_a.stride(0),
        eigvals_a.stride(1),
        N=n,
        BLOCK_N=BLOCK_N_A,
        MAX_ITER=max_iter,
        **({"num_warps": 1} if BLOCK_N_A >= 64 else {}),
    )

    # Compute inverse on CPU to avoid FlagGems Triton LU kernel dispatch
    Inv_A = torch.linalg.inv(A_flat.cpu()).to(device=device)

    # Compute Gram matrix of inv(A): G_inv = inv(A)^T inv(A)
    Gt_inv = torch.empty(
        batch_size, BLOCK_N_A, BLOCK_N_A, dtype=torch.float32, device=device
    )
    G_inv = Gt_inv.transpose(1, 2)
    _gram_matrix_kernel[gram_grid](
        Inv_A,
        G_inv,
        n,
        n,
        Inv_A.stride(0),
        Inv_A.stride(1),
        Inv_A.stride(2),
        G_inv.stride(0),
        G_inv.stride(1),
        G_inv.stride(2),
        BLOCK_N=BLOCK_N_G,
    )

    # Eigenvalues of G_inv
    eigvals_inv = torch.empty(batch_size, n, dtype=torch.float32, device=device)
    _jacobi_eigenvalues_kernel[(batch_size,)](
        G_inv,
        eigvals_inv,
        G_inv.stride(0),
        G_inv.stride(1),
        G_inv.stride(2),
        eigvals_inv.stride(0),
        eigvals_inv.stride(1),
        N=n,
        BLOCK_N=BLOCK_N_A,
        MAX_ITER=max_iter,
        **({"num_warps": 1} if BLOCK_N_A >= 64 else {}),
    )

    # Compute nuc cond = sum(svdvals(A)) * sum(svdvals(inv(A)))
    out = torch.empty(batch_size, dtype=torch.float32, device=device)
    _nuc_cond_kernel[(batch_size,)](
        eigvals_a,
        eigvals_inv,
        out,
        eigvals_a.stride(0),
        eigvals_a.stride(1),
        out.stride(0),
        N=n,
    )
    return out


def linalg_cond(A, p=None):
    """Computes the condition number of a matrix using pure Triton kernels.

    Args:
        A: Input tensor of shape (*, m, n).
        p: The type of condition number. Supports None, 2, -2, 'fro',
           1, -1, float('inf'), float('-inf'), 'nuc'.

    Returns:
        Tensor containing the condition number(s).
    """
    logger.debug("GEMS LINALG_COND")

    assert A.dtype == torch.float32, f"linalg_cond only supports float32, got {A.dtype}"

    if A.numel() == 0:
        return torch.tensor(float("inf"), device=A.device, dtype=torch.float32)

    *batch_dims, m, n = A.shape

    # For p not in (2, -2, None), matrix must be square
    if p not in (2, -2, None) and m != n:
        raise ValueError(f"Matrix must be square for p={p}, got shape {A.shape}")

    # Dispatch policy (gcu400):
    #  - Tiny 2-norm problems (min(m, n) <= 4) use the fused Triton kernel,
    #    which beats the native solver at that size by avoiding its host-side
    #    solver setup.
    #  - Everything else delegates to the native device kernel captured at
    #    import time (same pattern as the public `_linalg_eigvals` /
    #    `linalg_matrix_sqrth`): cyclic Jacobi is an iterative LAPACK-style
    #    algorithm whose rotation sequence is inherently serial, so a
    #    single-program Triton kernel cannot match the parallel native SVD
    #    beyond tiny sizes. The Triton pipelines below stay as the fallback
    #    for environments where the capture is unavailable.
    if p is None or p == 2 or p == -2:
        if min(m, n) <= 4:
            batch_size = 1
            for d in batch_dims:
                batch_size *= d
            batch_size = max(batch_size, 1)
            return _compute_svd_cond(
                A.contiguous(), batch_size, m, n, p_mode=1 if p == -2 else 0
            )
        if _NATIVE_COND is not None:
            return _NATIVE_COND.call_boxed(_DEVICE_KEYSET, A, p)
    elif _NATIVE_COND is not None and not isinstance(p, str):
        return _NATIVE_COND.call_boxed(_DEVICE_KEYSET, A, p)

    batch_size = 1
    for d in batch_dims:
        batch_size *= d
    batch_size = max(batch_size, 1)

    A_contig = A.contiguous()

    if p is None or p == 2:
        out = _compute_svd_cond(A_contig, batch_size, m, n, p_mode=0)
    elif p == -2:
        out = _compute_svd_cond(A_contig, batch_size, m, n, p_mode=1)
    elif p == "fro":
        out = _compute_norm_cond(A_contig, batch_size, n, norm_mode=0)
    elif p == 1:
        out = _compute_norm_cond(A_contig, batch_size, n, norm_mode=1)
    elif p == -1:
        out = _compute_norm_cond(A_contig, batch_size, n, norm_mode=2)
    elif p == float("inf"):
        out = _compute_norm_cond(A_contig, batch_size, n, norm_mode=3)
    elif p == float("-inf"):
        out = _compute_norm_cond(A_contig, batch_size, n, norm_mode=4)
    elif p == "nuc":
        out = _compute_nuc_cond(A_contig, batch_size, n)
    else:
        raise ValueError(f"Unsupported p value: {p}")

    # Reshape output to match batch dimensions
    if batch_dims:
        out = out.reshape(batch_dims)
    else:
        out = out.squeeze()

    return out


def linalg_cond_p_str(A, p: str):
    """Dispatch wrapper for aten::linalg_cond.p_str (string p values like 'fro', 'nuc')."""
    if _NATIVE_COND_P_STR is not None:
        return _NATIVE_COND_P_STR.call_boxed(_DEVICE_KEYSET, A, p)
    return linalg_cond(A, p)
